"use client";
import { useRef } from "react";
import {
  useScrollMotion,
  scrollUnits,
  scrollStage,
  type ScrollMotionProps,
  type ScrollItem,
} from "./scroll-shared";
import { scrollRandom, scrollEase, scrollStagger, scrollLerp } from "./scroll-math";
export interface MultiFlipProps extends ScrollMotionProps {
  items: readonly ScrollItem[];
  columns?: number;
  gap?: number;
  stagger?: number;
  rotation?: number;
  pileSpread?: number;
}
export function MultiFlip({
  items,
  columns = 3,
  gap = 16,
  stagger = 0.35,
  rotation = 26,
  pileSpread = 0.2,
  ...props
}: MultiFlipProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    props,
    ({ progress: p, width: w, height: h }) => {
      const cols = Math.max(
          1,
          Math.min(items.length || 1, Math.floor(columns), w < 480 ? 2 : columns),
        ),
        rows = Math.ceil(items.length / cols),
        g = Math.min(gap, w * 0.05),
        cw = Math.min(
          (w - g * (cols + 1)) / cols,
          ((h - g * (rows + 1)) / Math.max(1, rows)) * 0.77,
        ),
        ch = cw / 0.77,
        gw = cols * cw + (cols - 1) * g,
        gh = rows * ch + (rows - 1) * g;
      scrollUnits(root.current!).forEach((el, i) => {
        const q = scrollEase(scrollStagger(p, i, items.length, stagger)),
          x = (i % cols) * (cw + g) + (w - gw) / 2,
          y = Math.floor(i / cols) * (ch + g) + (h - gh) / 2;
        el.style.width = `${cw}px`;
        el.style.height = `${ch}px`;
        el.style.transform = `translate(${scrollLerp((w - cw) / 2 + (scrollRandom(i) - 0.5) * w * pileSpread, x, q)}px,${scrollLerp((h - ch) / 2 + (scrollRandom(i, 4) - 0.5) * h * pileSpread, y, q)}px) rotate(${(scrollRandom(i, 7) - 0.5) * rotation * 2 * (1 - q)}deg)`;
      });
    },
    `${items.map((x) => x.id).join(",")}:${columns}:${gap}:${stagger}:${rotation}:${pileSpread}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="multi-flip"
      className={props.className}
      style={{ ...scrollStage, ...props.style }}
    >
      {items.map((item) => (
        <div
          data-scroll-unit={item.id}
          key={item.id}
          className={item.className}
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "24%",
            height: "36%",
            borderRadius: 8,
            overflow: "hidden",
            boxShadow: "0 12px 25px #0002",
            ...item.style,
          }}
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}
